INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422586, 16261, 'The Guardian', 'en', 'Swift appeal likely as judge blocks Trump mail voting order', 'https://www.theguardian.com/us-news/live/2026/aug/28/donald-trump-mail-voting-tariffs-canada-space-nasa-march-on-washington-latest-news-updates', 'Judge Indira Talwani temporarily blocked US Postal Service from implementing new rule restricting mail-in voting Sign up for the US Breaking News email Donald Trump is still in Houston, Texas. Today, he’ll present the congressional Space Medal of Honor at 11am ET, and then he’ll call the International Space Station at 12pm ET, before traveling back to Washington. We’ll bring you the latest lines as that gets under way. Continue reading...', 'https://i.guim.co.uk/img/media/7e3cc0ed157e944759e1c275f3086262451cf34e/223_0_3334_2667/master/3334.jpg?width=140&quality=85&auto=format&fit=max&s=4f0992f546e07c0b0d737ae762f52577', '2026-08-28T12:20:36+00:00', '2026-08-28T12:49:05.856432'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422592, 16261, 'The Guardian', 'en', 'Pentagon’s blacklisting of Anthropic was unlawful, US judge rules', 'https://www.theguardian.com/technology/2026/aug/28/us-court-rules-pentagon-anthropic-ban-illegal-trump-claude-ai', 'Anthropic ​argued designation as ‘supply chain risk’ could cost the company billions ‌of dollars in lost business ‌and reputational harm A US federal judge ruled Thursday that sanctions imposed in February by the Trump administration against AI giant Anthropic were illegal, finding that the government had punished the artificial intelligence company for publicly criticising the Pentagon. “The empty invocation of national security is not a blank check to punish and retaliate against government critics,” Judge Rita Lin said in a 59-page decision. Continue reading...', 'https://i.guim.co.uk/img/media/cbc273f8b06b2ec975a7d6f57af674709dc1d9d0/303_0_3331_2666/master/3331.jpg?width=140&quality=85&auto=format&fit=max&s=4ea108ee0251325f535a8f6e10828ac1', '2026-08-28T03:34:35+00:00', '2026-08-28T12:49:07.331487'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
